// The three legs (Willison's lethal trifecta; Meta's Rule of Two): an agent may have at most two.
export interface AgentAccess {
  name: string;
  inputs: string[];   // text the agent reads that someone else wrote: tickets, diffs, Slack, web pages
  data: string[];     // private data it can reach: PHI, prod credentials, customer documents
  actions: string[];  // ways it changes state or talks outward: push, comment, post, apply
}
export type Leg = "A untrusted input" | "B private data" | "C outward action";

export const legs = (agent: AgentAccess): Leg[] => [
  ...(agent.inputs.length ? ["A untrusted input" as const] : []),
  ...(agent.data.length ? ["B private data" as const] : []),
  ...(agent.actions.length ? ["C outward action" as const] : []),
];

/** The leg we remove for every agent at Rhino: B. Fake seed data only, no PHI, no prod credentials. */
export const ruleOfTwo = (agent: AgentAccess): string | null => {
  const have = legs(agent);
  if (have.length < 3) return null;
  return `${agent.name} has all three legs; remove B (${agent.data.join(", ")}) or a person must approve every action`;
};
